module Mult(
  input         clock,
                reset,
  input  [31:0] io_valid,
                io_a,
                io_b,
  input         io_op,
                io_clear_valid,
  output [31:0] io_ready,
                io_c,
  output        io_low_nonzero,
  output [31:0] io_received
);

  wire [31:0] _adder4_io_sum;
  wire [31:0] _adder3_io_sum;
  wire [31:0] _adder2_io_sum;
  wire        _adder2_io_cout;
  wire [31:0] _adder1_io_sum;
  wire        _adder1_io_cout;
  reg  [31:0] p00;
  reg  [31:0] p01;
  reg  [31:0] p10;
  reg  [31:0] p11;
  reg  [31:0] received;
  reg  [31:0] ready1;
  reg  [31:0] ready2;
  reg  [31:0] adder2_io_a_REG;
  reg  [15:0] adder2_io_b_REG;
  reg  [31:0] adder4_io_a_REG;
  reg  [15:0] adder4_io_b_REG;
  reg         io_c_REG;
  reg         io_c_REG_1;
  wire [31:0] _GEN = io_clear_valid ? 32'h0 : io_valid;
  wire [31:0] _GEN_0 = {16'h0, io_a[15:0]};
  wire [31:0] _GEN_1 = {16'h0, io_b[15:0]};
  wire [31:0] _GEN_2 = {16'h0, io_b[31:16]};
  wire [31:0] _GEN_3 = {16'h0, io_a[31:16]};
  always @(posedge clock) begin
    p00 <= _GEN_0 * _GEN_1;
    p01 <= _GEN_0 * _GEN_2;
    p10 <= _GEN_3 * _GEN_1;
    p11 <= _GEN_3 * _GEN_2;
    adder2_io_a_REG <= _adder1_io_sum;
    adder2_io_b_REG <= p10[15:0];
    adder4_io_a_REG <= _adder3_io_sum + {31'h0, _adder1_io_cout};
    adder4_io_b_REG <= p10[31:16];
    io_c_REG <= io_op;
    io_c_REG_1 <= io_c_REG;
    if (reset) begin
      received <= 32'h0;
      ready1 <= 32'h0;
      ready2 <= 32'h0;
    end
    else begin
      received <= _GEN;
      ready1 <= _GEN;
      ready2 <= io_clear_valid ? 32'h0 : ready1;
    end
  end // always @(posedge)
  Adder adder1 (
    .io_a    (p00),
    .io_b    ({p01[15:0], 16'h0}),
    .io_sum  (_adder1_io_sum),
    .io_cout (_adder1_io_cout)
  );
  Adder adder2 (
    .io_a    (adder2_io_a_REG),
    .io_b    ({adder2_io_b_REG, 16'h0}),
    .io_sum  (_adder2_io_sum),
    .io_cout (_adder2_io_cout)
  );
  Adder adder3 (
    .io_a    (p11),
    .io_b    ({16'h0, p01[31:16]}),
    .io_sum  (_adder3_io_sum),
    .io_cout (/* unused */)
  );
  Adder adder4 (
    .io_a    (adder4_io_a_REG),
    .io_b    ({16'h0, adder4_io_b_REG}),
    .io_sum  (_adder4_io_sum),
    .io_cout (/* unused */)
  );
  assign io_ready = ready2;
  assign io_c = io_c_REG_1 ? _adder4_io_sum + {31'h0, _adder2_io_cout} : _adder2_io_sum;
  assign io_low_nonzero = |_adder2_io_sum;
  assign io_received = received;
endmodule

